import{G as e,W as t,n,rt as r}from"./chunks/framework.9o07hMZQ.js";var i=JSON.parse(`{"title":"XVoice Voice Tutorial","description":"","frontmatter":{},"headers":[],"relativePath":"en/tutorial/xvoice.md","filePath":"en/tutorial/xvoice.md","lastUpdated":0}`),a={name:`en/tutorial/xvoice.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="xvoice-voice-tutorial" tabindex="-1">XVoice Voice Tutorial <a class="header-anchor" href="#xvoice-voice-tutorial" aria-label="Permalink to “XVoice Voice Tutorial”">​</a></h1><p>This tutorial explains how to use the XVoice voice software for voice communication.</p><h2 id="what-is-xvoice" tabindex="-1">What is XVoice <a class="header-anchor" href="#what-is-xvoice" aria-label="Permalink to “What is XVoice”">​</a></h2><p>XVoice is the voice communication software of the XFLYSIM online flight platform. In airspace where ATC services are provided, voice crews need to use XVoice to communicate with controllers and other crews.</p><h2 id="installation-and-login" tabindex="-1">Installation and Login <a class="header-anchor" href="#installation-and-login" aria-label="Permalink to “Installation and Login”">​</a></h2><ol><li>Download and install the XVoice client.</li><li>Log in with the account and password registered on the online flight website.</li></ol><h2 id="connecting-to-the-server" tabindex="-1">Connecting to the Server <a class="header-anchor" href="#connecting-to-the-server" aria-label="Permalink to “Connecting to the Server”">​</a></h2><ol><li>Open XVoice, select the XFLYSIM server and connect.</li><li>After connecting, confirm that the software shows an online status.</li></ol><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>After entering controlled airspace, follow controller instructions and keep the voice channel clear.</li><li>During an activity, all aircraft pilots within the activity airspace must have two-way voice communication capability.</li><li>For crews who are unable to use voice communication, the platform provides English text-based ATC services.</li><li>Please use civil language and communicate in harmony. Abusing crew members or controllers is prohibited; any such conduct results in immediate permanent grounding.</li></ul>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};